# Let me compare input and output element by element
d_in15 = [7, 7, 9, 7, 7, 9, 7, 7, 9, 7, 7, 7, 9, 9, 7]
d_out15 = [7, 7, 9, 7, 7, 9, 7, 7, 9, 7, 7, 9, 7, 9, 7, 7, 9, 7, 7, 9, 7, 7, 9, 7, 7, 9, 9, 9, 9, 7]

print("Index: Input -> Output")
for i in range(30):
    if i < 15:
        inp_val = d_in15[i]
    else:
        inp_val = "N/A"
    out_val = d_out15[i]
    if inp_val != "N/A" and inp_val == out_val:
        print(f"{i:3d}: {inp_val} -> {out_val} (SAME)")
    elif inp_val != "N/A":
        print(f"{i:3d}: {inp_val} -> {out_val} (DIFF)")
    else:
        print(f"{i:3d}: ? -> {out_val} (EXTEND)")

# Hmm, there are many differences. Let me check if output is somehow derived from
# a DIFFERENT INDEXING of the input

# What if output[i] = d_in15[f(i)] where f is some function?
# Let me reverse engineer f

def find_mapping(d_in, d_out, max_w=35):
    """Find f(i) such that d_out[i] = d_in[f(i)]"""
    mapping = {}
    for i in range(max_w):
        # Find which input position could generate d_out[i]
        candidates = [j for j in range(len(d_in)) if d_in[j] == d_out[i]]
        if i not in mapping:
            mapping[i] = candidates[0] if candidates else None
    return mapping

